:root {
  --ink: #18333d;
  --muted: #66818a;
  --paper: #fffdf7;
  --line: #d7e1dc;
  --sea: #0d7180;
  --sea-pale: #dcefee;
  --signal: #f4a847;
  --signal-pale: #fff0d8;
  --white: #ffffff;
}

.practice-card {
  width: 480px;
  box-sizing: border-box;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background-color: var(--paper);
  color: var(--ink);
}

.card-header,
.card-footer,
.meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-header {
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
}

.live-chip {
  padding: 6px 9px;
  border-radius: 999px;
  background-color: var(--signal-pale);
  color: var(--sea);
  font-size: 12px;
  font-weight: 700;
}

.lesson-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 12px;
  padding: 14px 0;
}

.signal-panel,
.detail-panel {
  box-sizing: border-box;
  min-height: 118px;
  padding: 13px;
  border-radius: 12px;
}

.signal-panel {
  background-color: var(--sea-pale);
}

.detail-panel {
  border: 1px solid var(--line);
}

.signal-word {
  display: block;
  margin: 3px 0 12px;
  color: var(--sea);
  font-size: 25px;
  letter-spacing: 0.13em;
  line-height: 1;
}

.flag-row {
  display: flex;
  gap: 6px;
}

.flag {
  width: 22px;
  height: 22px;
  border: 2px solid var(--sea);
  border-radius: 4px;
  box-sizing: border-box;
}

.flag-one,
.flag-three {
  background-color: var(--signal);
}

.flag-two {
  background-color: var(--white);
}

.flag-four {
  background-color: var(--sea);
}

.meta-list {
  display: grid;
  gap: 5px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.meta-row {
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}

.meta-row:last-child {
  border-bottom: 0;
}

.meta-label {
  color: var(--muted);
}

.meta-value {
  font-weight: 700;
}

.card-footer {
  gap: 14px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.progress {
  width: 108px;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background-color: var(--line);
}

.progress-fill {
  display: block;
  width: 60%;
  height: 100%;
  border-radius: inherit;
  background-color: var(--signal);
}

.action {
  border: 0;
  border-radius: 9px;
  padding: 9px 12px;
  background-color: var(--sea);
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
}

.action span {
  margin-left: 5px;
  font-size: 16px;
}
